#!/usr/bin/env python3
"""Run a command with the repository vLLM source and matching wheel binaries."""

import importlib.metadata
import os
import shutil
import signal
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "vendor" / "vllm" / "vllm"
EXPECTED = "0.26.1rc1.dev75+gdc1be7903"


def wheel_package_files(dist):
    """Only distribution-owned package assets, excluding generated bytecode."""
    return sorted(
        Path(*p.parts[1:])
        for p in (dist.files or [])
        if p.parts[0] == "vllm" and "__pycache__" not in p.parts and p.suffix != ".pyc"
    )


def stage_package(source, wheel, package, files):
    """Repository source wins; wheel-only libraries/support assets fill gaps."""
    shutil.copytree(
        source, package, ignore=shutil.ignore_patterns("__pycache__", "*.pyc")
    )
    for relative in files:
        target = package / relative
        asset = wheel / relative
        if not asset.is_file():
            raise FileNotFoundError(f"Missing pinned wheel asset: {relative}")
        if not target.exists():
            target.parent.mkdir(parents=True, exist_ok=True)
            target.symlink_to(asset)
    version = wheel / "_version.py"
    if version.exists():
        target = package / "_version.py"
        if target.is_symlink():
            target.unlink()
        shutil.copy2(version, target)


def main():
    if len(sys.argv) < 2:
        raise SystemExit("Usage: python tools/vllm_runtime.py COMMAND [ARGS...]")
    command = sys.argv[1:]
    # Compare environment paths without resolving venv symlinks to system Python.
    executable = shutil.which(command[0])
    if executable is None or os.path.abspath(executable) != os.path.abspath(
        sys.executable
    ):
        raise SystemExit(
            "Run the child with the same Python as the launcher: "
            f"{sys.executable} tools/vllm_runtime.py {sys.executable} -m MODULE ..."
        )
    dist = importlib.metadata.distribution("vllm")
    if dist.version != EXPECTED:
        raise SystemExit(f"Expected vLLM wheel {EXPECTED}; found {dist.version}")
    wheel = Path(dist.locate_file("vllm")).resolve()

    def interrupted(signum, frame):
        raise KeyboardInterrupt(f"Signal {signum}")

    signal.signal(signal.SIGTERM, interrupted)
    stage_parent = os.environ.get("SEMANTIC_VLLM_STAGE_PARENT")
    if stage_parent:
        Path(stage_parent).mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(
        prefix="semantic-vllm-", dir=stage_parent
    ) as directory:
        package = Path(directory) / "vllm"
        stage_package(SOURCE, wheel, package, wheel_package_files(dist))
        env = os.environ.copy()
        env["PYTHONPATH"] = os.pathsep.join(
            [directory, str(ROOT), env.get("PYTHONPATH", "")]
        )
        env.setdefault("VLLM_WSL2_ENABLE_PIN_MEMORY", "1")
        child = subprocess.Popen(command, env=env)
        try:
            return child.wait()
        finally:
            if child.poll() is None:
                child.terminate()
                try:
                    child.wait(timeout=3)
                except subprocess.TimeoutExpired:
                    child.kill()
                    child.wait(timeout=1)


if __name__ == "__main__":
    raise SystemExit(main())
